import json, os, re, glob
import xml.etree.ElementTree as ET
from collections import defaultdict

data_path='/root/supplier_contact.json'
work_dir='/tmp/hwpx_work'

with open(data_path,'r',encoding='utf-8') as f:
    data=json.load(f)

# Collect placeholders found for debugging
ph_pat=re.compile(r'\{\{([^}]+)\}\}')
found=set()
for fpath in glob.glob(os.path.join(work_dir,'**','*'), recursive=True):
    if not os.path.isfile(fpath):
        continue
    try:
        txt=open(fpath,'r',encoding='utf-8',errors='ignore').read()
    except Exception:
        continue
    for m in ph_pat.finditer(txt):
        found.add(m.group(1))

print('JSON keys:', sorted(data.keys()))
print('Found placeholders:', sorted(found))
missing=[k for k in found if k not in data]
extra=[k for k in data.keys() if k not in found]
print('Missing-in-JSON:', missing)
print('Unused-JSON:', extra)

# Process XML files
for fpath in glob.glob(os.path.join(work_dir, '**', '*.xml'), recursive=True):
    raw=open(fpath,'r',encoding='utf-8',errors='ignore').read()
    if '{{' not in raw:
        continue

    # Discover namespaces and register so write preserves prefixes
    namespaces={}
    for event, (prefix, uri) in ET.iterparse(fpath, events=['start-ns']):
        if prefix in namespaces and namespaces[prefix]==uri:
            continue
        namespaces[prefix]=uri
        ET.register_namespace(prefix, uri)

    tree=ET.parse(fpath)
    root=tree.getroot()

    hp_ns=namespaces.get('hp')
    if not hp_ns:
        raise RuntimeError(f'No hp namespace in {fpath}; namespaces={namespaces}')

    HP=lambda local: '{%s}%s'%(hp_ns, local)

    # Parent map for removals / paragraph tracking
    parent_map={c:p for p in root.iter() for c in p}

    modified_p_elems=set()

    # 1) Replace placeholders in normal text/tail occurrences
    for elem in root.iter():
        changed=False
        if elem.text and '{{' in elem.text:
            new=elem.text
            for k,v in data.items():
                new=new.replace('{{'+k+'}}', str(v))
            if new!=elem.text:
                elem.text=new
                changed=True
        if elem.tail and '{{' in elem.tail:
            new=elem.tail
            for k,v in data.items():
                new=new.replace('{{'+k+'}}', str(v))
            if new!=elem.tail:
                elem.tail=new
                changed=True
        if changed:
            # bubble up to containing paragraph
            cur=elem
            while cur is not None and cur.tag!=HP('p'):
                cur=parent_map.get(cur)
            if cur is not None:
                modified_p_elems.add(cur)

    # 2) Handle split placeholders across <hp:t> within a <hp:run>
    for run in root.iter(HP('run')):
        t_elems=list(run.iter(HP('t')))
        if not t_elems:
            continue
        combined=''.join((t.text or '') for t in t_elems)
        if '{{' not in combined:
            continue
        new=combined
        for k,v in data.items():
            new=new.replace('{{'+k+'}}', str(v))
        if new!=combined:
            t_elems[0].text=new
            for t in t_elems[1:]:
                t.text=''
            # mark modified paragraph
            cur=run
            while cur is not None and cur.tag!=HP('p'):
                cur=parent_map.get(cur)
            if cur is not None:
                modified_p_elems.add(cur)

    # 3) Remove linesegarray in modified paragraphs
    for p in modified_p_elems:
        for ls in list(p.iter(HP('linesegarray'))):
            parent=parent_map.get(ls)
            if parent is not None:
                parent.remove(ls)

    tree.write(fpath, xml_declaration=True, encoding='utf-8')
    print(f'Modified {fpath}: paragraphs updated={len(modified_p_elems)}')

# Verify no placeholders remain in text files
remaining=[]
for fpath in glob.glob(os.path.join(work_dir,'**','*'), recursive=True):
    if not os.path.isfile(fpath):
        continue
    try:
        txt=open(fpath,'r',encoding='utf-8',errors='ignore').read()
    except Exception:
        continue
    if '{{' in txt:
        remaining.append(fpath)

if remaining:
    print('ERROR: Remaining placeholders in:')
    for f in remaining:
        print(' -', f)
        # print unique placeholders
        txt=open(f,'r',encoding='utf-8',errors='ignore').read()
        ups=sorted(set(ph_pat.findall(txt)))
        print('   placeholders:', ups)
    raise SystemExit(2)

print('Replacement complete: no remaining {{...}}')
